import unittest

from hourglass.rounding import round_span, rounded_labels
from hourglass.models import Span


class RoundSpanTests(unittest.TestCase):
    # ---
    def test_rounds_to_nearest_step(self):
        result = round_span(Span(547, 1028), 15)
        self.assertEqual(result, Span(540, 1035))

    # ---
    def test_halfway_goes_up(self):
        result = round_span(Span(65, 125), 10)
        self.assertEqual(result, Span(70, 130))

    # ---
    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 544), 15)


class LabelTests(unittest.TestCase):
    # ---
    def test_label_with_duration(self):
        spans = [Span(541, 1034), Span(0, 1440)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "00:00-24:00 (24h 0m)"]
        )

    # ---
    def test_empty_list(self):
        self.assertEqual(rounded_labels([], 10), [])


class StepTests(unittest.TestCase):
    # ---
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 90):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 600)], step)

    # ---
    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)

    # ---
    def test_good_steps_accepted(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            expected = ["00:00-12:00 (12h 0m)"]
            labels = rounded_labels([Span(0, 720)], step)
            self.assertEqual(labels, expected)
